 70	    REG_IF_ID reg_IF_ID(.clk(debug_clk),.rst(rst),.EN(reg_FD_EN),.Data_stall(reg_FD_stall),
 71	        .flush(reg_FD_flush),.PCOUT(PC_IF),.IR(inst_IF),
 72	
 73	        .IR_ID(inst_ID),.PCurrent_ID(PC_ID));
 74	    
 75	    CtrlUnit ctrl(.inst(inst_ID),.cmp_res(cmp_res_ID),.Branch(Branch_ctrl),.ALUSrc_A(ALUSrc_A_ctrl),
 76	        .ALUSrc_B(ALUSrc_B_ctrl),.DatatoReg(DatatoReg_ctrl),.RegWrite(RegWrite_ctrl),
